import math
    import random
    import time

    LANGUAGE_WRAPPER = 'In a three-player coin-tossing contest, Alfred, Bonnie, and Charlie use biased coins that land heads with probabilities {a_num}/{a_den}, {b_num}/{b_den}, and {c_num}/{c_den}, respectively. In each game, players take turns in cyclic order starting from the current starter; the first head wins that game. After a game ends, the player who tossed immediately before the winning head becomes the starter for the next game. Alfred starts the first game. Let the probability that Alfred wins the {k_th}th game be m/n in lowest terms. Compute the last {last_digits} digits of m+n.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Generate three distinct rational head probabilities in (0,1), avoiding 1/2
dens_pool = [5,6,7,8,9,10,11,12,13]
def pick_prob():
    den = rng.choice(dens_pool)
    # Avoid exact 1/2 and near-trivial extremes; keep 2..den-2
    candidates = [n for n in range(2, den-1) if 2*n != den]
    if not candidates:
        # fallback, shouldn't happen for given pool
        candidates = [n for n in range(1, den) if 2*n != den]
    num = rng.choice(candidates)
    return num, den
# Try until distinct probs
for _ in range(100):
    a_num, a_den = pick_prob()
    b_num, b_den = pick_prob()
    c_num, c_den = pick_prob()
    # Distinct probabilities
    if a_num * b_den == b_num * a_den:
        continue
    if a_num * c_den == c_num * a_den:
        continue
    if b_num * c_den == c_num * b_den:
        continue
    # Choose k and digits
    k_th = rng.randint(5, 30)
    last_digits = rng.choice([3, 4, 5])
    return {
        'a_num': a_num,
        'a_den': a_den,
        'b_num': b_num,
        'b_den': b_den,
        'c_num': c_num,
        'c_den': c_den,
        'k_th': k_th,
        'last_digits': last_digits
    }
# Fallback in rare case
# Use fixed nontrivial parameters
return {
    'a_num': 3, 'a_den': 7,
    'b_num': 5, 'b_den': 11,
    'c_num': 7, 'c_den': 13,
    'k_th': 17,
    'last_digits': 3
}

    def verifier(assign):
# Verify inputs and compute the required probability and last-digits answer
from fractions import Fraction
# Basic presence check
required = ['a_num','a_den','b_num','b_den','c_num','c_den','k_th','last_digits']
for key in required:
    if key not in assign:
        # Missing field
        return (False, None)
a_num = assign['a_num']; a_den = assign['a_den']
b_num = assign['b_num']; b_den = assign['b_den']
c_num = assign['c_num']; c_den = assign['c_den']
k_th = assign['k_th']
last_digits = assign['last_digits']
# Domain checks
if not (isinstance(a_num,int) and isinstance(a_den,int) and isinstance(b_num,int) and isinstance(b_den,int) and isinstance(c_num,int) and isinstance(c_den,int) and isinstance(k_th,int) and isinstance(last_digits,int)):
    # type error
    return (False, None)
if a_den <= 0 or b_den <= 0 or c_den <= 0:
    return (False, None)
if not (1 <= a_num < a_den and 1 <= b_num < b_den and 1 <= c_num < c_den):
    return (False, None)
# Avoid trivial 1/2 probabilities
if 2*a_num == a_den or 2*b_num == b_den or 2*c_num == c_den:
    return (False, None)
# k_th difficulty
if not (5 <= k_th <= 50):
    return (False, None)
if not (3 <= last_digits <= 6):
    return (False, None)
# Build probabilities
a = Fraction(a_num, a_den)
b = Fraction(b_num, b_den)
c = Fraction(c_num, c_den)
# Distinctness for nontrivial chain
if a == b or a == c or b == c:
    return (False, None)
# Fail probabilities
fA = Fraction(1,1) - a
fB = Fraction(1,1) - b
fC = Fraction(1,1) - c
# Ensure non-degenerate
if fA <= 0 or fB <= 0 or fC <= 0:
    return (False, None)
F = fA * fB * fC
if F <= 0 or F >= 1:
    # F in (0,1) expected; F=0 would imply someone always heads; F>=1 impossible
    return (False, None)
denom = Fraction(1,1) - F
# Win probabilities per starting state
# Start A: order A,B,C
WA_A = a / denom
WB_A = fA * b / denom
WC_A = fA * fB * c / denom
# Start B: order B,C,A
WB_B = b / denom
WC_B = fB * c / denom
WA_B = fB * fC * a / denom
# Start C: order C,A,B
WC_C = c / denom
WA_C = fC * a / denom
WB_C = fC * fA * b / denom
# Sanity: probabilities in (0,1) and rows sum to 1
def in01(x):
    return Fraction(0,1) < x and x < Fraction(1,1)
for triple in [(WA_A, WB_A, WC_A), (WA_B, WB_B, WC_B), (WA_C, WB_C, WC_C)]:
    if not all(in01(t) for t in triple):
        return (False, None)
    if triple[0] + triple[1] + triple[2] != Fraction(1,1):
        return (False, None)
# Transition matrix P for next game's starter states [A,B,C]
# From A: winner A -> next C; B -> next A; C -> next B
P = [
    [WB_A, WC_A, WA_A],  # row A: to A, B, C
    [WB_B, WC_B, WA_B],  # row B: to A, B, C
    [WB_C, WC_C, WA_C],  # row C: to A, B, C
]
# Initial state vector v: start at A
v = [Fraction(1,1), Fraction(0,1), Fraction(0,1)]
# Advance k_th - 1 transitions
steps = k_th - 1
for _ in range(steps):
    v_new = [Fraction(0,1), Fraction(0,1), Fraction(0,1)]
    # v_new[j] = sum_i v[i]*P[i][j]
    for j in range(3):
        s = Fraction(0,1)
        for i in range(3):
            s += v[i] * P[i][j]
        v_new[j] = s
    v = v_new
# Alfred's win probability on k_th game is dot(v, [WA_A, WA_B, WA_C])
wA_vec = [WA_A, WA_B, WA_C]
prob = v[0]*wA_vec[0] + v[1]*wA_vec[1] + v[2]*wA_vec[2]
# Reduce and compute last digits of m+n
m = prob.numerator
n = prob.denominator
modulus = 10 ** last_digits
answer = (m + n) % modulus
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

